style.css:
@-moz-document domain("youtube.com") {
/* Genel Arkaplan ve Görsel */
    body {
        background-image: url('https://images8.alphacoders.com/481/thumb-1920-481338.jpg');
        background-size: cover;
        background-position: center;
        color: #00FFFF; /* Neon mavi */
        font-family: Arial, sans-serif;
        overflow: hidden;
        background-attachment: fixed !important; /* Arka planın sabit kalmasını sağlar */
        background-color: transparent !important; /* Arka planın tamamen şeffaf olması için */
    }

    /* Şeffaflık ve Blur Uygulama */
    * {
        background-color: transparent !important;
        border: none !important;
    }

    /* Neon Butonlar ve Linkler */
    a, button, .ytp-button, .ytp-play-button, .style-scope.ytd-guide-entry-renderer, .yt-simple-endpoint, .ytp-chrome-top, .ytp-chrome-bottom, .ytp-volume-slider {
        color: #00FFFF !important;
        text-shadow: 0 0 10px #00FFFF, 0 0 20px #00FFFF, 0 0 30px #00FFFF !important;
        transition: all 0.3s ease !important;
        background-color: rgba(0, 0, 0, 0.4) !important; /* Şeffaf arkaplan */
        border: 2px solid rgba(0, 255, 255, 0.5) !important; /* Neon kenarlık */
    }

    /* Neon Butonlar ve Videoların Üzerine Gelindiğinde */
    button:hover, a:hover, .ytp-play-button:hover, .ytp-next-button:hover, .ytp-prev-button:hover, .ytp-volume-button:hover, .ytp-fullscreen-button:hover {
        color: #00FFFF !important;
        text-shadow: 0 0 20px #00FFFF, 0 0 30px #00FFFF, 0 0 40px #00FFFF !important;
        background-color: rgba(0, 0, 0, 0.6) !important;
        box-shadow: 0 0 20px #00FFFF !important;
    }

    /* Video Oynatıcı */
    .ytp-video-player {
        border: 3px solid #00FFFF !important;
        box-shadow: 0 0 15px #00FFFF !important;
    }

    /* Profil Fotoğrafı ve Yanındaki Öğeler */
    #avatar-btn img, .yt-simple-endpoint.ytd-channel-name {
        border: 2px solid #00FFFF !important;
        box-shadow: 0 0 10px #00FFFF !important;
    }

    /* Arama Butonu, Arama Kutusu */
    #search-input, #search-button {
        border: 2px solid #00FFFF !important;
        background-color: transparent !important;
        color: #00FFFF !important;
        transition: border 0.3s ease !important;
    }

    #search-input::placeholder {
        color: #00FFFF !important;
    }

    /* Arama Butonunun Hover Durumu */
    #search-button:hover {
        background-color: rgba(0, 0, 0, 0.6) !important;
        border: 2px solid #00FFFF !important;
    }

    /* Menü (Üç Çizgi Simgesi) */
    #guide-button {
        color: #00FFFF !important;
        text-shadow: 0 0 10px #00FFFF, 0 0 20px #00FFFF !important;
    }

    /* Neon Mavi Stil için Etkiler */
    .ytp-chrome-bottom, .ytp-chrome-top, .ytp-chrome-controls {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    /* İmleç üzerine neon etki */
    * {
        cursor: url('https://upload.wikimedia.org/wikipedia/commons/2/2e/Neon_Cursor.svg'), auto !important;
    }

    /* Sayfa Yüklenmesi ve Etkileşim Geçişi */
    .style-scope.ytd-video-primary-info-renderer {
        transition: all 0.5s ease !important;
    }

    /* Ana Sayfa ve Kanal Kısımlarının Neon Efekti */
    .ytd-guide-entry-renderer {
        color: #00FFFF !important;
        text-shadow: 0 0 10px #00FFFF, 0 0 20px #00FFFF !important;
        transition: all 0.3s ease !important;
    }

    /* Yorumlar, Açıklamalar ve Diğer Bölümler */
    .style-scope.ytd-comment-thread-renderer {
        border-bottom: 2px solid rgba(0, 255, 255, 0.5) !important;
        color: #00FFFF !important;
    }

    /* Video Başlıkları Neon Efekti */
    .yt-simple-endpoint.style-scope.ytd-video-primary-info-renderer {
        color: #00FFFF !important;
        text-shadow: 0 0 15px #00FFFF, 0 0 25px #00FFFF !important;
    }

    /* Video Durumu, Yükleniyor... ve Benzeri Metinler */
    .ytp-spinner {
        color: #00FFFF !important;
    }

    /* Video Sonrası Butonlar (Paylaş, Kaydet vb.) */
    .ytp-upnext-container button:hover {
        color: #00FFFF !important;
        text-shadow: 0 0 15px #00FFFF, 0 0 30px #00FFFF !important;
    }

    /* Ekstra Stil ve Efektler: */
    /* 1. Yükleme animasyonu */
    .ytp-spinner {
        animation: spin 2s linear infinite;
    }

    /* 2. Video başlığı animasyonu */
    .yt-simple-endpoint.style-scope.ytd-video-primary-info-renderer {
        animation: pulse 1.5s infinite;
    }

    /* 3. Sidebar menüsüne efekt */
    .ytd-guide-entry-renderer {
        transition: background-color 0.3s ease;
    }

    .ytd-guide-entry-renderer:hover {
        background-color: rgba(0, 255, 255, 0.2) !important;
    }

    /* 4. Ana sayfa butonları için efekt */
    .ytd-masthead {
        transition: background-color 0.3s ease;
    }

    .ytd-masthead:hover {
        background-color: rgba(0, 0, 0, 0.7) !important;
    }

    /* 5. Video oynatıcı kenarlık animasyonu */
    .ytp-video-player {
        border: 3px solid rgba(0, 255, 255, 0.8) !important;
        animation: borderPulse 3s infinite;
    }

    /* 6. Linklerin üzerine gelince renk değiştirmesi */
    a:hover {
        color: #00FFFF !important;
        text-decoration: underline !important;
    }

    /* 7. Profil fotoğrafı üzerine gelince etki */
    #avatar-btn:hover img {
        box-shadow: 0 0 20px #00FFFF !important;
        border: 2px solid #00FFFF !important;
    }

    /* 8. Video küçük resimlerinin üzerine gelindiğinde büyümesi */
    .yt-img-shadow:hover {
        transform: scale(1.05);
        transition: transform 0.3s ease;
    }

    /* 9. Arama kutusunun içine gelince arka planın koyulaşması */
    #search-input:focus {
        background-color: rgba(0, 0, 0, 0.5) !important;
        border: 2px solid #00FFFF !important;
    }

    /* 10. Video yüklenirken arka planın bulanıklaşması */
    .ytp-spinner {
        filter: blur(4px);
    }

    /* Animasyonlar için Keyframes */
    @keyframes spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
    }

    @keyframes pulse {
        0% { opacity: 0.8; }
        50% { opacity: 1; }
        100% { opacity: 0.8; }
    }

    @keyframes borderPulse {
        0% { border-color: rgba(0, 255, 255, 0.8); }
        50% { border-color: rgba(0, 255, 255, 0.5); }
        100% { border-color: rgba(0, 255, 255, 0.8); }
    }
}
